void force_change(const int* ptr) {
    // Casting away constness to modify internal state
    int* non_const_ptr = const_cast<int*>(ptr);
    *non_const_ptr = 42;
}

int original_val = 10;
// OK, original_val is truly non-const
force_change(&original_val);

// Example of removing const from a reference
void update_ref(const char& c) {
    char& mod_c = const_cast<char&>(c);
    mod_c = 'Z';
}
char letter = 'A';
update_ref(letter); // letter is now 'Z'
